package macro;
import star.common.*;import star.motion.*;import star.base.neo.*;import star.base.report.*;import star.flow.*;import star.vis.*;import java.nio.file.*;import java.util.*;
public class InspectHydroComparison extends StarMacro {
Simulation s;Path out;StringBuilder note=new StringBuilder();
FieldFunction ff(String name){return s.getFieldFunctionManager().getFunction(name);}
void table(String name,Collection<? extends NamedObject> parts,Representation rep,List<FieldFunction> fields)throws Exception{XyzInternalTable t=s.getTableManager().createTable(XyzInternalTable.class);t.getParts().setObjects(parts);t.setRepresentation(rep);t.setExtractVertexData(false);t.setFieldFunctions(fields);t.extract();t.export(out.resolve(name+".csv").toString());}

void setupAudit(List<Region> regions,List<Boundary> fixed,List<Boundary> flap)throws Exception{
StringBuilder b=new StringBuilder("time="+s.getSolution().getPhysicalTime()+" initialized_flag="+s.getSolution().isInitialized()+"\n");
for(Solver solver:s.getSolverManager().getObjects()){String cn=solver.getClass().getName();b.append("solver="+solver.getPresentationName()+" class="+cn);if(cn.toLowerCase(Locale.ROOT).contains("turb")||cn.contains("SegregatedFlowSolver"))try{b.append(" frozen="+solver.getFrozen());}catch(Exception e){b.append(" UNREAD_FROZEN_STATE="+e);}b.append("\n");}
for(SolverStoppingCriterion crit:s.getSolverStoppingCriterionManager().getObjects())if(crit instanceof InnerIterationStoppingCriterion)b.append("inner_iterations="+((InnerIterationStoppingCriterion)crit).getMaximumNumberInnerIterations()+" used="+crit.getIsUsed()+"\n");
ImplicitUnsteadySolver time=s.getSolverManager().getSolver(ImplicitUnsteadySolver.class);b.append("dt="+time.getTimeStep().getValue()+" time_discretization="+time.getTimeDiscretizationOption().getSelected()+"\n");
Set<PhysicsContinuum> pcs=new HashSet<>();for(Region r:regions){pcs.add(r.getPhysicsContinuum());b.append("region="+r.getPresentationName()+" motion="+r.getValues().get(MotionSpecification.class).getMotion()+"\n");for(Boundary wall:r.getBoundaryManager().getBoundaries()){b.append("boundary="+wall.getPresentationName()+" type="+wall.getBoundaryType()+"\n");for(Object condition:wall.getConditions().getObjects())if(condition instanceof EnumeratedOption)try{b.append("  option="+condition.getClass().getSimpleName()+" selected="+((EnumeratedOption)condition).getSelected()+"\n");}catch(Exception e){b.append("  UNREAD_BOUNDARY_OPTION="+condition.getClass().getSimpleName()+" "+e+"\n");}}}
for(PhysicsContinuum pc:pcs)for(Object model:pc.getModelManager().getObjects())b.append("model="+model.getClass().getName()+"\n");
for(Motion motion:s.get(MotionManager.class).getObjects())if(motion instanceof RotatingMotion){RotatingMotion rot=(RotatingMotion)motion;b.append("rotation="+rot.getPresentationName()+" specification="+rot.getRotationSpecification()+"\n");if(rot.getRotationSpecification() instanceof RotationAngle)b.append("angle_definition="+((RotationAngle)rot.getRotationSpecification()).getRotationAngle().getDefinition()+"\n");b.append("hinge_transformed="+rot.transformInitialCoordinate(new Vector3(.952,.02,.02128173276776986))+"\n");}
List<String> names=new ArrayList<>();for(FieldFunction f:s.getFieldFunctionManager().getObjects()){String n=f.getFunctionName(),low=n.toLowerCase(Locale.ROOT);if(low.contains("velocity")&&(low.contains("mesh")||low.contains("grid")||low.contains("wall")||low.contains("boundary")))names.add(n);}
b.append("motion_velocity_fields="+names+"\n");
for(String name:names){FieldFunction f=ff(name);try{if(f.getTypeOption().getSelected()!=FieldFunctionTypeOption.Type.VECTOR.getValue())continue;MaxReport max=s.getReportManager().createReport(MaxReport.class);max.getParts().setObjects(regions);max.setFieldFunction(f.getMagnitudeFunction());b.append(name+"_max_magnitude="+max.getReportMonitorValue()+"\n");s.getReportManager().removeObjects(max);}catch(Exception e){b.append("OPTIONAL_VELOCITY_FIELD_UNAVAILABLE "+name+" "+e+"\n");}}
Files.writeString(out.resolve("native_setup.txt"),b.toString());
List<FieldFunction> wallFields=new ArrayList<>();for(String n:List.of("Pressure","AbsolutePressure","WallYplus","OversetCellStatus","OversetErrorStatus"))if(s.getFieldFunctionManager().hasFunction(n))wallFields.add(ff(n));
int j=0;for(List<Boundary> parts:List.of(fixed,flap))if(!parts.isEmpty())table((j++==0?"main":"flap")+"_wall_status",parts,s.getRepresentationManager().getObject("Volume Mesh"),wallFields);
}

public void execute(){s=getActiveSimulation();Path root=Paths.get("F:/ntnu/flap_control/hydro_validation_2606_20261102");String variant=System.getenv("NTNU_HYDRO_VARIANT");out=root.resolve("audit/comparison_"+variant+"_"+System.getenv("NTNU_HYDRO_RUN_ID"));
try{
Path input=Paths.get(s.getSessionPath()).toAbsolutePath().normalize();if(!input.startsWith(root.resolve("cases")))throw new IllegalStateException("Own copy only");Files.createDirectories(out);
s.getSimulationIterator().getAutoSave().setEnabled(false);s.getSimulationIterator().getAutoSave().setAutoSaveBatch(false);double time=s.getSolution().getPhysicalTime();note.append("source="+input+"\ntime="+time+"\n");
List<Region> regions=new ArrayList<>();List<Boundary> fixed=new ArrayList<>(),flap=new ArrayList<>();
for(Region r:s.getRegionManager().getRegions())if(r.getPhysicsContinuum()!=null&&r.getPhysicsContinuum().getPresentationName().equals("HYDRO water SST singlephase")){regions.add(r);for(Boundary b:r.getBoundaryManager().getBoundaries()){note.append("boundary="+r+"|"+b+"|"+b.getBoundaryType()+"\n");if(b.getBoundaryType() instanceof WallBoundary&&!b.getPresentationName().endsWith("bottom")){if(b.getPresentationName().contains("Hydro_Flap"))flap.add(b);else fixed.add(b);}}}
setupAudit(regions,fixed,flap);
Representation volume=s.getRepresentationManager().getObject("Volume Mesh");Representation full=variant.equals("SP_C")?s.getRepresentationManager().getObject("Overset Mesh"):null;
int j=0;for(List<Boundary> walls:List.of(fixed,flap)){String group=j++==0?"main":"flap";if(walls.isEmpty())continue;ForceReport f=s.getReportManager().createReport(ForceReport.class);f.setPressureOption(FluidLoadsReportPressureOption.SP_UC);f.getDirection().setComponents(0,0,1);f.getParts().setObjects(walls);f.getReportMonitorValue();note.append(group+"_pressure_force="+f.getPressureValue()+"\n"+group+"_shear_force="+f.getShearValue()+"\n"+group+"_total_force="+f.getValue()+"\n");table(group+"_wall",walls,volume,List.of(ff("Pressure"),ff("AbsolutePressure"),ff("WallYplus"))); }
for(Interface iface:s.getInterfaceManager().getObjects())if(iface instanceof IndirectRegionInterface){IndirectRegionInterface ov=(IndirectRegionInterface)iface;note.append("interface="+ov+" regions="+ov.getRegion0()+","+ov.getRegion1()+"\nzero_gap="+ov.getIsZeroGapInterface()+" close_proximity="+ov.getCloseProximity()+" prism_shrink="+ov.getPrismLayerShrinkage()+" alternate_hole="+ov.getUseAlternateHoleCutting()+" zero_donor_check="+ov.getConditions().get(OversetHoleCuttingOptions.class).getBoolean("ZeroDonorCheckOption")+" errors_as_warning="+ov.getTreatErrorAsWarning()+" verified_hole="+ov.getVerifiedHoleCutting()+" modified_donor="+ov.getModifiedDonorSearch()+" interpolation="+ov.getConditions().get(OversetMeshInterpolationOption.class).getSelected()+"\n");
if(ov.getTreatErrorAsWarning()||!ov.getConditions().get(OversetHoleCuttingOptions.class).getBoolean("ZeroDonorCheckOption"))throw new IllegalStateException("Required native strict connectivity check disabled");
ov.setVerbosity(IndirectRegionInterfaceVerbosity.DIAGNOSTICS);s.getInterfaceManager().resetInterfaces(List.of(iface));s.getInterfaceManager().initializeInterfaces(List.of(iface));
for(OversetInterpolationQualityReportOption.Type type:List.of(OversetInterpolationQualityReportOption.Type.MAXIMUM,OversetInterpolationQualityReportOption.Type.EUCLIDEAN,OversetInterpolationQualityReportOption.Type.THRESHOLD)){OversetInterpolationQualityReport q=s.getReportManager().createReport(OversetInterpolationQualityReport.class);q.setOversetInterface(ov);q.getNormType().setSelected(type);q.setAbsoluteValue(true);q.setInterpolationQualityThreshold(.01);note.append("native_interpolation_"+type+"="+q.getReportMonitorValue()+"\n");}
}
List<FieldFunction> fields=new ArrayList<>();for(String name:List.of("Pressure","AbsolutePressure","Volume","CellQuality","WallDistance","TurbulentKineticEnergy","SpecificDissipationRate","TurbulentViscosityRatio","OversetCellStatus","OversetCellType","OversetErrorStatus","OversetInterpolationType","Overset Interpolation Cell Size Ratio"))if(s.getFieldFunctionManager().hasFunction(name))fields.add(ff(name));for(int axis=0;axis<3;axis++)fields.add(ff("Velocity").getComponentFunction(axis));
for(Region r:regions){table(r.getPresentationName()+"_volume",List.of(r),volume,fields);
if(variant.equals("SP_C")&&full!=null){PlaneSection p=s.getPartManager().createImplicitPart(List.of(r),List.of(0.,1.,0.),List.of(0.,.02,0.),0,1,new DoubleVector(new double[]{0}));Scene sc=s.getSceneManager().createScene("Connectivity "+r.getPresentationName());sc.initializeAndWait();ScalarDisplayer ds=sc.getDisplayerManager().createScalarDisplayer("Status");ds.getInputParts().setObjects(p);ds.setRepresentation(full);ds.getScalarDisplayQuantity().setFieldFunction(ff("OversetCellStatus"));ds.getScalarDisplayQuantity().setRangeMin(-2);ds.getScalarDisplayQuantity().setRangeMax(1);ds.setDisplayMeshBoolean(true);sc.getCurrentView().setInput(new DoubleVector(new double[]{.95,.02,.02}),new DoubleVector(new double[]{.95,-3,.02}),new DoubleVector(new double[]{0,0,1}),.40,1,s.getCoordinateSystemManager().getLabCoordinateSystem(),false);sc.printAndWait(out.resolve(r.getPresentationName()+"_overset_status.png").toString(),1,1400,900);table(r.getPresentationName()+"_full_plane",List.of(p),full,List.of(ff("OversetCellStatus"),ff("OversetCellType"),ff("OversetErrorStatus"),ff("OversetInterpolationType"),ff("Overset Interpolation Cell Size Ratio")));}}
Files.writeString(out.resolve("diagnostic.txt"),note.toString());if(s.getSolution().getPhysicalTime()!=time)throw new IllegalStateException("Audit advanced physical time");
Files.writeString(out.resolve("status.json"),"{\"status\":\"inspection_complete\",\"solver_steps\":0,\"simulation_saved\":false,\"physical_time_preserved\":true,\"training_approved\":false}");
}catch(Exception e){try{Files.writeString(out.resolve("diagnostic.txt"),note.toString());Files.writeString(out.resolve("error.txt"),e.toString());}catch(Exception ignored){}throw new RuntimeException(e);}
}}
